<section class="single-herbs-guide__section" aria-labelledby="topic-six-foundations"><h4 id="topic-six-foundations"><?php echo s($toxintext('Herbs that Clear Heat and Resolve Toxicity: general introduction', 'Hierbas que aclaran Calor y resuelven toxicidad: introducción general')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($toxintext('These herbs treat concentrated Heat-toxin expressed as red, hot, painful swelling, pus, abscess, ulceration or severe throat inflammation. The decisive Board skill is matching the toxic process to its location.', 'Estas hierbas tratan Calor-Toxina concentrado expresado como inflamación roja, caliente y dolorosa, pus, absceso, ulceración o inflamación grave de garganta. La habilidad Board decisiva es relacionar el proceso tóxico con su localización.')); ?></p><div class="single-herbs-guide__pattern"><article><strong><?php echo s($toxintext('Typical presentation', 'Presentación típica')); ?></strong><span><?php echo s($toxintext('Redness, swelling, heat, pain, pus, sore throat, abscess or toxic rash with a red tongue and rapid pulse.', 'Enrojecimiento, inflamación, calor, dolor, pus, garganta dolorosa, absceso o erupción tóxica con lengua roja y pulso rápido.')); ?></span></article><article><strong><?php echo s($toxintext('Choose by location', 'Elige por localización')); ?></strong><span><?php echo s($toxintext('Broad/exterior, Heart clump, breast, Summerheat, phlegmy throat or severe toxic throat.', 'Amplio/exterior, masa de Corazón, mama, Calor de Verano, garganta con Flema o garganta tóxica grave.')); ?></span></article><article><strong><?php echo s($toxintext('Safety boundary', 'Límite de seguridad')); ?></strong><span><?php echo s($toxintext('Abscess, airway swelling, high fever or systemic toxicity requires biomedical assessment; this guide teaches recognition, not self-treatment.', 'Absceso, inflamación de vía aérea, fiebre alta o toxicidad sistémica requiere evaluación biomédica; esta guía enseña reconocimiento, no autotratamiento.')); ?></span></article></div><p class="single-herbs-guide__scope-note"><strong><?php echo s($toxintext('General precautions:', 'Precauciones generales:')); ?></strong> <?php echo s($toxintext('most are cold and may injure Spleen/Stomach Yang when overused. Strong throat herbs require particular dose care. Distinguish true Heat-toxin from deficient, chronic or already-draining lesions.', 'la mayoría son frías y pueden lesionar Yang de Bazo/Estómago si se usan en exceso. Las hierbas fuertes para garganta requieren especial cuidado de dosis. Distingue Calor-Toxina verdadero de lesiones deficientes, crónicas o ya drenando.')); ?></p><aside class="single-herbs-guide__memory-path" aria-label="<?php echo s($toxintext('Toxicity response team memory path', 'Recorrido mnemotécnico del equipo contra toxicidad')); ?>"><p class="single-herbs-guide__memory-line"><?php echo s($toxintext('The house now sounds a toxicity alarm. Six responders take different rooms.', 'La casa activa una alarma de toxicidad. Seis respondedores ocupan cuartos distintos.')); ?></p><p><?php echo s($toxintext('Jin Yin Hua patrols outside and inside; Lian Qiao breaks the Heart-room knot; Pu Gong Ying treats the breast wing; He Ye opens the summer umbrella; She Gan clears phlegmy throat pipes; Shan Dou Gen extinguishes the most toxic throat fire.', 'Jin Yin Hua patrulla afuera y adentro; Lian Qiao rompe el nudo del cuarto de Corazón; Pu Gong Ying atiende el ala mamaria; He Ye abre el paraguas de verano; She Gan limpia tuberías de garganta con Flema; Shan Dou Gen apaga el fuego tóxico más intenso de garganta.')); ?></p><p><strong><?php echo s($toxintext('Same alarm, different room.', 'Misma alarma, cuarto diferente.')); ?></strong></p></aside><h5 class="single-herbs-guide__catalog-heading"><?php echo s($toxintext('Current Board category herbs', 'Hierbas de la categoría Board vigente')); ?></h5><p class="single-herbs-guide__catalog-intro"><?php echo s($toxintext('Study these six herbs named in the module first. The annex remains separate.', 'Estudia primero estas seis hierbas nombradas en el módulo. El anexo permanece separado.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach ($toxinherbs as $categoryherb): ?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($toxintext('In Board category list', 'En el listado de la categoría Board')); ?></span></div><p><?php echo s($categoryherb['identity']); ?></p></li><?php endforeach; ?></ol><div class="single-herbs-guide__annex"><h5 class="single-herbs-guide__catalog-heading"><?php echo s($toxintext('Annex · Additional official recognition herbs', 'Anexo · Hierbas oficiales adicionales para reconocimiento')); ?></h5><p class="single-herbs-guide__catalog-intro"><?php echo s($toxintext('These official Appendix A herbs expand recognition without changing this module’s six-herb sequence.', 'Estas hierbas oficiales del Apéndice A amplían reconocimiento sin cambiar la secuencia de seis hierbas del módulo.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach ($toxinannex as $categoryherb): ?><li class="single-herbs-guide__category-herb"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge single-herbs-guide__category-herb-badge--outside"><?php echo s($toxintext('Official annex recognition', 'Reconocimiento oficial de anexo')); ?></span></div><p><?php echo s($categoryherb['note']); ?></p></li><?php endforeach; ?></ol></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-six-yang-title"><h4 id="topic-six-yang-title"><?php echo s($toxintext('Yang comparative fingerprint', 'Huella comparativa de Yang')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($toxintext('The figures separate dispersing strength from organ location. Values are relative study indices, not clinical percentages.', 'Las figuras separan fuerza dispersante de localización orgánica. Los valores son índices relativos de estudio, no porcentajes clínicos.')); ?></p><div class="single-herbs-guide__yang-charts"><?php foreach ($toxincharts as $chart): ?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart['title']); ?></h5><small><?php echo s($chart['figure']); ?></small><?php foreach ($chart['items'] as $herbname => $value): ?><div class="single-herbs-guide__yang-bar"><span><?php echo s($herbname); ?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo (int) $value; ?>%"></span></span><b><?php echo (int) $value; ?></b></div><?php endforeach; ?></article><?php endforeach; ?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($toxintext('Reading rule:', 'Regla de lectura:')); ?></strong> <?php echo s($toxintext('Jin Yin Hua and Lian Qiao share broad dispersing power; the remaining choice becomes anatomical—Stomach/breast, Lung with Phlegm, or the intensely toxic throat.', 'Jin Yin Hua y Lian Qiao comparten potencia dispersante amplia; la elección restante se vuelve anatómica: Estómago/mama, Pulmón con Flema o garganta intensamente tóxica.')); ?></p></section>

