__yang-control single-herbs-guide__yang-control--flip" type="button" data-yang-flip data-show-label="<?php echo s($toxintext('Show answer', 'Mostrar respuesta')); ?>" data-hide-label="<?php echo s($toxintext('Show question', 'Mostrar pregunta')); ?>"><?php echo s($toxintext('Show answer', 'Mostrar respuesta')); ?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($toxintext('Next', 'Siguiente')); ?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($toxintext('Card', 'Tarjeta')); ?> 1 <?php echo s($toxintext('of', 'de')); ?> <?php echo count($toxinquestions); ?></p></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-six-recall-title"><h4 id="topic-six-recall-title"><?php echo s($toxintext('Quick recall', 'Repaso rápido')); ?></h4><div class="single-herbs-guide__recall"><details><summary><?php echo s($toxintext('Which pair leads Yin Qiao San?', '¿Qué pareja dirige Yin Qiao San?')); ?></summary><p><strong>Jin Yin Hua + Lian Qiao.</strong> <?php echo s($toxintext('One is sweeter and gentler; the other targets Heart, clumps and urination.', 'Una es más dulce y suave; la otra actúa en Corazón, masas y orina.')); ?></p></details><details><summary><?php echo s($toxintext('Which herb points directly to breast abscess?', '¿Qué hierba señala directamente absceso mamario?')); ?></summary><p><strong>Pu Gong Ying.</strong> <?php echo s($toxintext('Its Liver-Stomach focus is the recognition key.', 'Su enfoque Hígado-Estómago es la clave de reconocimiento.')); ?></p></details><details><summary><?php echo s($toxintext('She Gan or Shan Dou Gen when Phlegm dominates?', '¿She Gan o Shan Dou Gen cuando domina Flema?')); ?></summary><p><strong>She Gan.</strong> <?php echo s($toxintext('Choose Shan Dou Gen when severe toxic swelling dominates instead.', 'Elige Shan Dou Gen cuando domina inflamación tóxica grave.')); ?></p></details><details><summary><?php echo s($toxintext('What is the He Ye trap?', '¿Cuál es la trampa de He Ye?')); ?></summary><p><?php echo s($toxintext('It appears in this module title, but its classic identity is Summerheat clearing, clear-Yang lifting and bleeding control.', 'Aparece en el título del módulo, pero su identidad clásica es aclarar Calor de Verano, elevar Yang claro y controlar sangrado.')); ?></p></details></div></section>

